  it("should evict expired window records when maximoDeMarcas is reached", async () => {
    const limitador = async () => ({ tipo: "requisicoes-por-ip", ms: 100 });
    const rateLimiter = criarRateLimiter({ limitador, maximoDeMarcas: 1 });

    const res = {
      set: () => {},
      status: vi.fn().mockReturnThis(),
      send: vi.fn()
    };
    const next = vi.fn();

    vi.useFakeTimers();
    vi.setSystemTime(1000);

    await rateLimiter({ method: "GET", path: "/usuarios", ip: "127.0.0.1" }, res, next);

    // Advance time so that 127.0.0.1's window has expired (fim = 1100 <= agora 2000)
    vi.setSystemTime(2000);

    await rateLimiter({ method: "GET", path: "/usuarios", ip: "127.0.0.2" }, res, next);

    vi.useRealTimers();
    expect(res.status).toHaveBeenCalledTimes(2);
