    const limitador = async () => ({ tipo: "requisicoes-por-ip", ms: 1000 });
    const rateLimiter = criarRateLimiter({ limitador, maximoDeMarcas: 10 });

    const req = { method: "GET", path: "/usuarios", ip: "127.0.0.1" };
    const res = {
      set: () => {},
      status: vi.fn().mockReturnThis(),
      send: vi.fn()
    };
    const next = vi.fn();

    vi.useFakeTimers();
    vi.setSystemTime(1000);

    // First block at t=1000. Window ends at t=2000. Folga ends at t=3000.
    await rateLimiter(req, res, next);

    // At t=2500, fim (2000) <= marcado + FOLGA (2000 + 1000 = 3000), so it is considered duplicate
    vi.setSystemTime(2500);
    await rateLimiter(req, res, next);

    // At t=3001, fim (2000) > marcado + FOLGA (1000 + 1000 = 2000), so it is NOT considered duplicate
    vi.setSystemTime(3001);
    await rateLimiter(req, res, next);

    vi.useRealTimers();
    expect(res.status).toHaveBeenCalledTimes(3);
